'use strict';
const rangeSelectionBase={library,handleAction};
function rangeScopeMarkup(recursive,context){return '<label class="directory-file-scope" title="'+(recursive?'已开启：显示当前文件夹及所有下级文件夹内的资料':'未开启：只显示当前文件夹内的资料；开启后包含所有下级文件夹')+'"><input type="checkbox" data-directory-scope="'+context+'" '+(recursive?'checked':'')+' aria-label="包含下级文件夹"><span>包含下级文件夹</span></label>';}

function rangeSelectionContext(){const items=libItems(),all=items.filter(x=>x.kind==='file'&&auditFileAccess(x.file).read).map(x=>x.file.id),page=pageItems(items,state.page,libraryPrefs.pageSize).filter(x=>x.kind==='file'&&auditFileAccess(x.file).read).map(x=>x.file.id),selected=new Set(state.librarySelected);return{all,page,chosen:all.filter(id=>selected.has(id)),pageChosen:page.filter(id=>selected.has(id)),outside:libSelected().filter(d=>!all.includes(d.id)).length};}
library=function(){const root=document.createElement('div');root.innerHTML=rangeSelectionBase.library();const c=rangeSelectionContext(),check=root.querySelector('[data-lib-change="page"]');if(check){check.setAttribute('aria-label','全选当前页文件，不含文件夹');check.title='只选择或取消当前页文件，不影响其他页';check.setAttribute('aria-checked',c.pageChosen.length&&c.pageChosen.length<c.page.length?'mixed':c.page.length&&c.pageChosen.length===c.page.length?'true':'false');check.indeterminate=c.pageChosen.length>0&&c.pageChosen.length<c.page.length;const label=document.createElement('label');label.className='range-page-label';check.replaceWith(label);label.append(check,document.createTextNode('本页'));}
 const all=c.all.length>0&&c.chosen.length===c.all.length,pageAll=c.page.length>0&&c.pageChosen.length===c.page.length;
 const nativeScope=root.querySelector('[data-lib-change="scope"]');if(nativeScope){nativeScope.hidden=true;nativeScope.tabIndex=-1;}
 const scope=state.space+' / '+(folderPath(state.folder)||'根目录')+'；'+(state.libraryRecursive?'当前文件夹及子文件夹':'当前文件夹')+(state.query?'；名称含“'+state.query+'”':'');
 const banner=document.createElement('div');banner.className='range-selection-bar range-table-top directory-file-toolbar';
 banner.innerHTML=rangeScopeMarkup(!!state.libraryRecursive,'library')+'<span class="range-selected-description" role="status" title="'+E(scope)+'">'+(!all&&c.chosen.length?(pageAll?'已选本页 <strong>'+c.page.length+'</strong> 份':'当前结果已选 <strong>'+c.chosen.length+'</strong> / '+c.all.length+' 份'):'')+'</span><div class="range-selection-actions">'+A(all?'已选全部页（'+c.all.length+' 份）':'选择全部页（'+c.all.length+' 份）','range-select-all','title="选择当前目录、搜索和筛选条件下全部页的文件" '+(!c.all.length||all?'disabled':''))+(all&&c.all.length>c.page.length?A('仅保留本页','range-keep-page',!c.page.length?'disabled':''):'')+(c.chosen.length?A('取消本范围选择','range-clear','title="其他范围的已选文件保留"'):'')+'</div>';
 root.querySelector('.lib-table-scroll')?.before(banner);

 requestAnimationFrame(()=>{const el=$('[data-lib-change="page"]');if(el){el.indeterminate=c.pageChosen.length>0&&c.pageChosen.length<c.page.length;}});return root.innerHTML;};
handleAction=function(action,el){if(action==='range-scope-set'){const picker=el.dataset.context==='picker',select=$(picker?'.picker-center [data-v3-change="picker-scope"]':'.lib-files [data-lib-change="scope"]');if(select){select.value=el.dataset.value;select.dispatchEvent(new Event('change',{bubbles:true}));}return;}if(state.view==='library'&&['lib-prev','lib-next'].includes(action)){const pages=Math.max(1,Math.ceil(libItems().length/libraryPrefs.pageSize));state.page=Math.max(1,Math.min(pages,state.page+(action==='lib-next'?1:-1)));render();return;}if(!['range-select-all','range-keep-page','range-clear'].includes(action))return rangeSelectionBase.handleAction(action,el);const c=rangeSelectionContext(),scope=new Set(c.all);if(action==='range-select-all')state.librarySelected=[...new Set([...state.librarySelected,...c.all])];else{const keep=action==='range-keep-page'?new Set(c.page):new Set();state.librarySelected=state.librarySelected.filter(id=>!scope.has(id)||keep.has(id));}render();toast(action==='range-select-all'?'已选择当前结果全部 '+c.all.length+' 份文件。':action==='range-keep-page'?'当前结果仅保留本页选择，其他范围已选文件保留。':'已取消当前结果范围的选择，其他范围已选文件保留。');};
render();

window.addEventListener('change',event=>{const context=event.target.dataset.directoryScope;if(!context)return;event.stopImmediatePropagation();const picker=context==='picker',select=$(picker?'.picker-center [data-v3-change="picker-scope"]':'.lib-files [data-lib-change="scope"]');if(select){select.value=event.target.checked?'recursive':'direct';select.dispatchEvent(new Event('change',{bubbles:true}));}},true);
